  "statement": "Em 1996, 25% da energia produzida por um país era obtida de usinas hidrelétricas. Em 2016, essa produção passou a ser de 40%. Admitindo-se que de 25%, em 1996, para 40%, em 2016, o crescimento anual da porcentagem foi geométrico, é correto afirmar que o fator constante de crescimento anual foi igual a",
