    "Incorreta (C). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa E.",
    "Incorreta (D). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa E.",
    "Correta (E). Conforme a resolução: Sendo $x$ o total da energia produzida pelo país: em 1996 a energia hidroelétrica era $a_1 = 0{,}25x$ e em 2016 (21º ano) era $a_{21} = 0{,}40x$. Pela lei da progressão geométrica: $a_{21} = a_1 \\cdot q^{20} \\implies 0{,}40x = 0{,}25x \\cdot q^{20} \\implies q^{20} = \\frac{0{,}40}{0{,}25} = 1{,}6 \\implies q = \\sqrt[20]{1{,}6}$."
