    "Correta (D). Conforme a resolução: Considerando o ar como gás ideal em temperatura constante: $p_0 V_0 = p_f V_f \\implies p_0 A h_0 = p_f A h_f \\implies 2{,}0 \\times 20 = p_f \\times 16 \\implies p_f = 2{,}5\\ \\mathrm{atm}$. O aumento de pressão foi $\\Delta p = 2{,}5 - 2{,}0 = 0{,}5\\ \\mathrm{atm}$. Como $10\\ \\mathrm{m}$ de coluna d'água correspondem a $1{,}0\\ \\mathrm{atm}$, o mergulhador aprofundou-se em mais $5{,}0\\ \\mathrm{m}$.",
