    "Correta (C). Conforme a resolução: A questão aborda dois aspectos do colonialismo na África: a catequese de um lado, e o etnocentrismo europeu (travestido de teoria científica), de outro. A primeira, praticada na verdade desde o século XV, contribuiu indiretamente para o processo de sujeição dos nativos, em função de sua aculturação e da absorção dos valores europeus. O segundo, já em pleno neocolonialismo, foi utilizado para impor a justificativa civilizatória do “fardo do homem branco”.",
