    "Correta (D). Conforme a resolução: A frase efetivamente pronunciada por Washington Luis foi “a agitação operária é uma questão que interessa mais à ordem pública do que à ordem social”, tendo sido sintetizada na expressão “a questão operária é uma questão (e não “caso”) de polícia”. De qualquer forma, ela reflete a incompreensão e intolerância das autoridades da Primeira República em relação ao movimento operário. Ação policial violenta, repressão às greves, prisões arbitrárias, deportação de militantes estrangeiros, proibição de organizações sindicais e empastelamento de gráficas libertárias eram práticas recorrentes contra os integrantes do proletariado até a ascensão de Getúlio Vargas.",
