  "statement": "A energia liberada na combustão do etanol hidratado é cerca de 70% da energia liberada na combustão de igual volume de gasolina. Considere que o calor específico da água líquida seja 1 cal · g–1 · oC–1. Em um experimento, a combustão de um volume V de etanol hidratado em um calorímetro permitiu elevar a temperatura de 200 g de água líquida de 25 oC a 60 oC. Caso fosse utilizado nesse experimento igual volume de gasolina no lugar do etanol, a temperatura dessa mesma massa de água iria variar de 25 oC até",
