      "expected": "A ligação é iônica. (1 ponto) Cálcio e cloro localizam-se em posições extremas na classificação periódica, sendo grande a diferença de eletronegatividade entre eles, o que resulta em ligação iônica. (1 ponto) Aceitar: cálcio é metal alcalino terroso e cloro é halogênio, portanto tem carater ametálico: o cálcio tende a perder elétrons e o cloro tende a receber para que fiquem com eletrosfera igual à de gás nobre.",
